query.base:
FROM metrics-gcp.cloudstorage.otel-default
// Scope to Cloud Storage. This data stream is shared with every other GCP service collected by the
// receiver, so both the resource-type filter and the metric-presence filter are mandatory.
| WHERE resource.attributes.gcp.resource_type == "gcs_bucket"
    AND `metrics.storage.googleapis.com/api/request_count` IS NOT NULL
//
// --- Response-code classification --------------------------------------------------------------
// Cloud Storage returns canonical status strings (OK, NOT_FOUND, UNAVAILABLE, ...), never numeric
// HTTP codes. The client-fault list below is the ONLY enumerated list in this rule: anything that
// is not OK, not a listed client fault and not a throttle is treated as a SERVICE fault. Codes that
// are new or absent from your estate therefore surface here rather than being silently dropped.
// Add a code to this list to stop it paging; remove one to make the rule stricter.
| EVAL is_client_fault = attributes.response_code IN (
      "NOT_FOUND", "PERMISSION_DENIED", "UNAUTHENTICATED", "INVALID_ARGUMENT",
      "FAILED_PRECONDITION", "OUT_OF_RANGE", "ALREADY_EXISTS", "CANCELLED")
// Rate limiting is a saturation signal with its own rule (gcp_cloudstorage_otel-request-throttling);
// excluded here so one hot-bucket incident does not page twice.
| EVAL is_throttle = attributes.response_code == "RESOURCE_EXHAUSTED"
      OR attributes.response_code LIKE "*RATE_LIMIT*"
      OR attributes.response_code LIKE "*QUOTA*"
      OR attributes.response_code LIKE "*TOO_MANY*"
| EVAL is_service_fault = attributes.response_code != "OK"
      AND NOT is_client_fault
      AND NOT is_throttle
//
// --- Aggregation -------------------------------------------------------------------------------
// request_count is a ~60s delta counter stored as a gauge: SUM it, never apply RATE() or any other
// counter function. This is the same aggregation shape the availability SLIs use.
| STATS total_requests         = SUM(`metrics.storage.googleapis.com/api/request_count`),
        service_fault_requests = SUM(`metrics.storage.googleapis.com/api/request_count`) WHERE is_service_fault,
        service_fault_codes    = VALUES(attributes.response_code) WHERE is_service_fault,
        affected_methods       = VALUES(attributes.method) WHERE is_service_fault
    BY resource.attributes.bucket_name, resource.attributes.location
| EVAL service_fault_requests = COALESCE(service_fault_requests, 0)

breach.segment:
// Volume floor: stops a near-idle bucket paging on one or two retryable blips.
WHERE total_requests >= 100 AND service_fault_requests >= 10
// Cast before dividing: request_count is a long, so `a / b` would be integer division.
| EVAL service_fault_pct = ROUND(service_fault_requests::DOUBLE / total_requests * 100.0, 3)
// Service-side faults should sit at ~0. Lower towards 0.1 for buckets on a user-facing critical
// path; raise to 2-5 for batch workloads with aggressive client-side retry.
| WHERE service_fault_pct > 1.0
| SORT service_fault_pct DESC
| LIMIT 50
